const http = require('http');
const fs = require('fs');
const path = require('path');

const url = http://127.0.0.1:64221/status;

http.get(url, (res) => {
  let body = '';
  res.on('data', (chunk) => { body += chunk; });
  res.on('end', () => {
    const data = JSON.parse(body);
    const outDir = path.join(__dirname, 'results');
    fs.mkdirSync(outDir, { recursive: true });
    fs.writeFileSync(path.join(outDir, 'status.json'), JSON.stringify({ status: data.status }, null, 2) + '\n');
    console.log('wrote results/status.json');
  });
}).on('error', (err) => {
  console.error(err);
  process.exit(1);
});

